/* ------------------------------------------------------------------ */
/* NEXORA domain model                                                 */
/*                                                                     */
/* Every entity the ERP persists. IDs are opaque strings generated by  */
/* `generateId`. Money and quantities are plain numbers. Timestamps are */
/* ISO-8601 strings; day keys are `YYYY-MM-DD` (see src/lib/dates.ts).  */
/* ------------------------------------------------------------------ */

export type ID = string;
export type ISODateTime = string;
export type DateKey = string;
export type CurrencyCode = string;

export interface BaseEntity {
  id: ID;
  createdAt: ISODateTime;
  updatedAt?: ISODateTime;
}

/* ----------------------------- Access ----------------------------- */

export type Role =
  | "owner"
  | "admin"
  | "manager"
  | "cashier"
  | "accountant"
  | "viewer";

export type Resource =
  | "dashboard"
  | "analytics"
  | "customers"
  | "suppliers"
  | "products"
  | "categories"
  | "units"
  | "warehouses"
  | "branches"
  | "inventory"
  | "sales"
  | "purchasing"
  | "finance"
  | "hr"
  | "reports"
  | "search"
  | "users"
  | "settings"
  | "audit";

export type Action =
  | "view"
  | "create"
  | "update"
  | "delete"
  | "approve"
  | "export"
  | "manage";

export interface Permission {
  id: ID;
  resource: Resource;
  actions: Action[];
  roles: Role[];
}

export interface User extends BaseEntity {
  name: string;
  email: string;
  /** DEMO ONLY. Plain text, never a real credential. */
  password: string;
  role: Role;
  status: "active" | "invited" | "deactivated";
  jobTitle?: string;
  lastLoginAt?: ISODateTime;
}

export interface SessionUser {
  id: ID;
  name: string;
  email: string;
  role: Role;
}

/* --------------------------- Configuration ------------------------ */

export type Industry =
  | "retail"
  | "distribution"
  | "manufacturing"
  | "services"
  | "hospitality"
  | "healthcare"
  | "technology"
  | "other";

export type PrimaryMetric =
  | "revenue"
  | "profit"
  | "cash"
  | "stock"
  | "orders";

export interface BusinessProfile {
  id: ID;
  name: string;
  legalName?: string;
  industry: Industry;
  currency: CurrencyCode;
  timezone: string;
  fiscalYearStart: DateKey;
  defaultTaxRate: number;
  email?: string;
  phone?: string;
  address?: string;
  city?: string;
  country?: string;
  taxId?: string;
  website?: string;
  primaryMetric: PrimaryMetric;
  revenueTarget: number;
  expenseTarget: number;
  onboardingDone: boolean;
  createdAt: ISODateTime;
  updatedAt?: ISODateTime;
}

export interface AppSettings {
  id: ID;
  theme: "light" | "dark" | "system";
  currencyDecimals: number;
  dateFormat: "iso" | "us" | "eu";
  defaultWarehouseId: ID | null;
  defaultBranchId: ID | null;
  defaultPaymentTerms: number;
  lowStockThreshold: number;
  reduceMotion: boolean;
  updatedAt?: ISODateTime;
}

export interface Branch extends BaseEntity {
  code: string;
  name: string;
  address?: string;
  city?: string;
  phone?: string;
  status: "active" | "inactive";
}

export interface Warehouse extends BaseEntity {
  code: string;
  name: string;
  branchId: ID | null;
  isDefault: boolean;
  status: "active" | "inactive";
}

/* ---------------------------- Master data ------------------------- */

export interface Customer extends BaseEntity {
  code: string;
  name: string;
  contactName?: string;
  email?: string;
  phone?: string;
  address?: string;
  city?: string;
  country?: string;
  taxId?: string;
  website?: string;
  tags: string[];
  creditLimit: number;
  paymentTerms: number;
  currency: CurrencyCode;
  openingBalance: number;
  status: "active" | "archived";
  notes?: string;
}

export interface Supplier extends BaseEntity {
  code: string;
  name: string;
  contactName?: string;
  email?: string;
  phone?: string;
  address?: string;
  city?: string;
  country?: string;
  taxId?: string;
  website?: string;
  tags: string[];
  paymentTerms: number;
  currency: CurrencyCode;
  openingBalance: number;
  status: "active" | "archived";
  notes?: string;
}

export interface Category extends BaseEntity {
  code: string;
  name: string;
  parentId: ID | null;
  description?: string;
  status: "active" | "archived";
}

export interface Unit extends BaseEntity {
  code: string;
  name: string;
  decimals: number;
  status: "active" | "archived";
}

export interface Product extends BaseEntity {
  sku: string;
  name: string;
  barcode?: string;
  categoryId: ID | null;
  unitId: ID | null;
  supplierId: ID | null;
  costPrice: number;
  sellPrice: number;
  taxRate: number;
  reorderLevel: number;
  trackStock: boolean;
  status: "active" | "draft" | "archived";
  description?: string;
}

/* ---------------------------- Inventory --------------------------- */

export interface StockBalance extends BaseEntity {
  productId: ID;
  warehouseId: ID;
  onHand: number;
  reserved: number;
}

export type StockMovementType =
  | "opening"
  | "receipt"
  | "delivery"
  | "sale"
  | "return_in"
  | "return_out"
  | "transfer_in"
  | "transfer_out"
  | "adjustment"
  | "reservation"
  | "reservation_release";

export interface StockMovement extends BaseEntity {
  date: DateKey;
  productId: ID;
  warehouseId: ID;
  type: StockMovementType;
  /** Signed: positive increases on-hand, negative decreases it. */
  quantity: number;
  balanceAfter: number;
  unitCost: number;
  refType: string;
  refId: ID;
  refNumber?: string;
  notes?: string;
  userId?: ID;
}

export interface StockTransferLine {
  id: ID;
  productId: ID;
  quantity: number;
  receivedQuantity: number;
}

export interface StockTransfer extends BaseEntity {
  number: string;
  date: DateKey;
  fromWarehouseId: ID;
  toWarehouseId: ID;
  status: "draft" | "in_transit" | "received" | "cancelled";
  lines: StockTransferLine[];
  notes?: string;
  createdBy: ID;
}

export interface StockReservation extends BaseEntity {
  refType: "sales_order";
  refId: ID;
  refNumber: string;
  productId: ID;
  warehouseId: ID;
  quantity: number;
  status: "active" | "released" | "fulfilled";
  releasedAt?: ISODateTime;
}

export interface StockAdjustmentLine {
  id: ID;
  productId: ID;
  quantityDelta: number;
  unitCost?: number;
}

export interface StockAdjustment extends BaseEntity {
  number: string;
  date: DateKey;
  warehouseId: ID;
  reason: "count_correction" | "damage" | "theft" | "other";
  status: "pending" | "approved" | "rejected";
  lines: StockAdjustmentLine[];
  notes?: string;
  requestedBy: ID;
  decidedBy?: ID;
  decidedAt?: ISODateTime;
}

/* ------------------------- Shared document lines ------------------ */

export interface DocumentLine {
  id: ID;
  productId: ID;
  description: string;
  quantity: number;
  unitPrice: number;
  discountPercent: number;
  taxRate: number;
  /** Captured at document time. Never recalculated from current price. */
  lineTotal: number;
}

export interface DocumentTotals {
  subtotal: number;
  discountTotal: number;
  taxTotal: number;
  total: number;
}

/* ------------------------------- Sales ---------------------------- */

export interface Quotation extends BaseEntity {
  number: string;
  date: DateKey;
  validUntil: DateKey;
  customerId: ID;
  branchId: ID | null;
  warehouseId: ID | null;
  status: "draft" | "sent" | "accepted" | "rejected" | "expired" | "converted";
  lines: DocumentLine[];
  subtotal: number;
  discountTotal: number;
  taxTotal: number;
  total: number;
  currency: CurrencyCode;
  salesRepId?: ID;
  notes?: string;
  convertedToOrderId?: ID;
}

export type SalesOrderStatus =
  | "draft"
  | "pending"
  | "approved"
  | "fulfilled"
  | "cancelled";

export interface SalesOrder extends BaseEntity {
  number: string;
  date: DateKey;
  customerId: ID;
  branchId: ID | null;
  warehouseId: ID;
  status: SalesOrderStatus;
  quotationId: ID | null;
  lines: DocumentLine[];
  subtotal: number;
  discountTotal: number;
  taxTotal: number;
  total: number;
  currency: CurrencyCode;
  paymentTerms: number;
  notes?: string;
  approvedBy?: ID;
  approvedAt?: ISODateTime;
}

export interface Delivery extends BaseEntity {
  number: string;
  date: DateKey;
  orderId: ID;
  customerId: ID;
  warehouseId: ID;
  status: "draft" | "shipped" | "delivered" | "cancelled";
  lines: DocumentLine[];
  driverNote?: string;
  createdBy: ID;
}

export type InvoiceStatus =
  | "draft"
  | "issued"
  | "partial"
  | "paid"
  | "overdue"
  | "void"
  | "refunded";

export interface SalesInvoice extends BaseEntity {
  number: string;
  date: DateKey;
  dueDate: DateKey;
  customerId: ID;
  branchId: ID | null;
  orderId: ID | null;
  deliveryId: ID | null;
  status: InvoiceStatus;
  lines: DocumentLine[];
  subtotal: number;
  discountTotal: number;
  taxTotal: number;
  total: number;
  paidAmount: number;
  currency: CurrencyCode;
  notes?: string;
}

export interface CustomerReturn extends BaseEntity {
  number: string;
  date: DateKey;
  customerId: ID;
  invoiceId: ID | null;
  warehouseId: ID;
  status: "pending" | "approved" | "received" | "rejected" | "cancelled";
  lines: DocumentLine[];
  reason: string;
  refundMethod: "credit_note" | "cash_refund";
  subtotal: number;
  taxTotal: number;
  total: number;
  createdAt: ISODateTime;
}

/* ----------------------------- Purchasing ------------------------- */

export interface PurchaseRequest extends BaseEntity {
  number: string;
  date: DateKey;
  requestedBy: ID;
  departmentId: ID | null;
  warehouseId: ID;
  status: "draft" | "pending" | "approved" | "rejected" | "converted";
  priority: "low" | "normal" | "high";
  lines: DocumentLine[];
  subtotal: number;
  taxTotal: number;
  total: number;
  reason?: string;
  decidedBy?: ID;
  decidedAt?: ISODateTime;
  convertedToOrderId?: ID;
}

export type PurchaseOrderStatus =
  | "draft"
  | "sent"
  | "partially_received"
  | "received"
  | "cancelled";

export interface PurchaseOrder extends BaseEntity {
  number: string;
  date: DateKey;
  expectedDate: DateKey;
  supplierId: ID;
  warehouseId: ID;
  requestId: ID | null;
  status: PurchaseOrderStatus;
  lines: DocumentLine[];
  subtotal: number;
  discountTotal: number;
  taxTotal: number;
  total: number;
  currency: CurrencyCode;
  notes?: string;
}

export interface GoodsReceiptLine {
  id: ID;
  productId: ID;
  orderedQuantity: number;
  receivedQuantity: number;
  unitCost: number;
}

export interface GoodsReceipt extends BaseEntity {
  number: string;
  date: DateKey;
  orderId: ID;
  supplierId: ID;
  warehouseId: ID;
  status: "draft" | "posted" | "partial";
  lines: GoodsReceiptLine[];
  notes?: string;
  postedAt?: ISODateTime;
  createdBy: ID;
}

export interface SupplierBill extends BaseEntity {
  number: string;
  date: DateKey;
  dueDate: DateKey;
  supplierId: ID;
  orderId: ID | null;
  receiptId: ID | null;
  status: InvoiceStatus;
  lines: DocumentLine[];
  subtotal: number;
  discountTotal: number;
  taxTotal: number;
  total: number;
  paidAmount: number;
  currency: CurrencyCode;
  notes?: string;
}

export interface PurchaseReturn extends BaseEntity {
  number: string;
  date: DateKey;
  supplierId: ID;
  warehouseId: ID;
  receiptId: ID | null;
  status: "pending" | "approved" | "shipped" | "rejected" | "cancelled";
  lines: DocumentLine[];
  reason: string;
  subtotal: number;
  taxTotal: number;
  total: number;
}

/* ------------------------------ Finance --------------------------- */

export type AccountType = "asset" | "liability" | "equity" | "revenue" | "expense";

export interface Account extends BaseEntity {
  code: string;
  name: string;
  type: AccountType;
  parentId: ID | null;
  description?: string;
  isSystem: boolean;
  status: "active" | "archived";
}

export type JournalStatus = "draft" | "posted" | "reversed";

export interface JournalLine {
  id: ID;
  entryId: ID;
  accountId: ID;
  debit: number;
  credit: number;
  memo?: string;
  partyType?: "customer" | "supplier" | "employee" | null;
  partyId?: ID | null;
}

export interface JournalEntry extends BaseEntity {
  number: string;
  date: DateKey;
  memo: string;
  refType: string;
  refId: ID | null;
  refNumber?: string;
  status: JournalStatus;
  totalDebit: number;
  totalCredit: number;
  lines: JournalLine[];
  postedAt?: ISODateTime;
  reversedByEntryId?: ID;
  reversesEntryId?: ID;
  createdBy: ID;
}

export type PaymentDirection = "inbound" | "outbound";

export interface Payment extends BaseEntity {
  number: string;
  date: DateKey;
  direction: PaymentDirection;
  method: "cash" | "bank_transfer" | "card" | "cheque" | "other";
  partyType: "customer" | "supplier";
  partyId: ID;
  /** Payer for inbound, payee for outbound. */
  partyName: string;
  amount: number;
  currency: CurrencyCode;
  bankAccountId: ID | null;
  reference?: string;
  status: "pending" | "cleared" | "void";
  notes?: string;
  journalEntryId?: ID;
}

export interface PaymentAllocation extends BaseEntity {
  paymentId: ID;
  targetType: "sales_invoice" | "supplier_bill";
  targetId: ID;
  targetNumber: string;
  amount: number;
}

export interface FiscalPeriod extends BaseEntity {
  name: string;
  startDate: DateKey;
  endDate: DateKey;
  status: "open" | "closed";
  closedAt?: ISODateTime;
}

export interface Expense extends BaseEntity {
  number: string;
  date: DateKey;
  accountId: ID;
  amount: number;
  currency: CurrencyCode;
  payee: string;
  method: Payment["method"];
  branchId: ID | null;
  status: "draft" | "recorded" | "void";
  notes?: string;
  journalEntryId?: ID;
  createdBy: ID;
}

/* -------------------------------- HR ------------------------------ */

export interface Department extends BaseEntity {
  code: string;
  name: string;
  managerId: ID | null;
  description?: string;
  status: "active" | "archived";
}

export interface Employee extends BaseEntity {
  code: string;
  name: string;
  email: string;
  phone?: string;
  departmentId: ID | null;
  designation: string;
  joinDate: DateKey;
  employmentType: "full_time" | "part_time" | "contract";
  status: "active" | "on_leave" | "terminated";
  /** Restricted to owner, admin and accountant roles. */
  salary: number;
  currency: CurrencyCode;
  bankAccount?: string;
  address?: string;
  leaveBalance: number;
}

export type AttendanceStatus =
  | "present"
  | "absent"
  | "late"
  | "half_day"
  | "leave"
  | "remote";

export interface Attendance extends BaseEntity {
  employeeId: ID;
  date: DateKey;
  checkIn: string | null;
  checkOut: string | null;
  status: AttendanceStatus;
  minutesWorked: number;
  notes?: string;
}

export type LeaveType = "annual" | "sick" | "unpaid" | "parental" | "other";

export interface LeaveRequest extends BaseEntity {
  employeeId: ID;
  type: LeaveType;
  startDate: DateKey;
  endDate: DateKey;
  days: number;
  reason: string;
  status: "pending" | "approved" | "rejected" | "cancelled";
  reviewedBy?: ID;
  reviewedAt?: ISODateTime;
}

export interface PayrollLine {
  id: ID;
  employeeId: ID;
  baseSalary: number;
  allowances: number;
  overtime: number;
  grossPay: number;
  deductions: number;
  netPay: number;
  notes?: string;
}

export interface PayrollRun extends BaseEntity {
  number: string;
  year: number;
  month: number;
  periodLabel: string;
  status: "draft" | "approved" | "paid";
  lines: PayrollLine[];
  grossTotal: number;
  deductionTotal: number;
  netTotal: number;
  journalEntryId?: ID;
  approvedBy?: ID;
  approvedAt?: ISODateTime;
  paidAt?: ISODateTime;
}

/* ----------------------------- System ----------------------------- */

export type ApprovalRefType =
  | "sales_order"
  | "purchase_request"
  | "stock_adjustment"
  | "payroll_run"
  | "journal_entry";

export interface Approval extends BaseEntity {
  refType: ApprovalRefType;
  refId: ID;
  refNumber: string;
  requestedBy: ID;
  requestedAt: ISODateTime;
  status: "pending" | "approved" | "rejected";
  decidedBy?: ID;
  decidedAt?: ISODateTime;
  comment?: string;
}

export type AuditAction =
  | "create"
  | "update"
  | "delete"
  | "approve"
  | "reject"
  | "post"
  | "reverse"
  | "login"
  | "logout"
  | "import"
  | "export"
  | "reset";

export interface AuditLog {
  id: ID;
  at: ISODateTime;
  actorId: ID;
  actorName: string;
  action: AuditAction;
  entity: string;
  entityId: ID | null;
  entityNumber?: string;
  summary: string;
  before?: Record<string, unknown> | null;
  after?: Record<string, unknown> | null;
}

export interface DocumentSequence {
  id: ID;
  prefix: string;
  next: number;
  padding: number;
}

/* --------------------------- Data bundles ------------------------- */

export interface ERPDataState {
  business: BusinessProfile | null;
  settings: AppSettings | null;
  branches: Branch[];
  warehouses: Warehouse[];
  customers: Customer[];
  suppliers: Supplier[];
  categories: Category[];
  units: Unit[];
  products: Product[];
  stockBalances: StockBalance[];
  stockMovements: StockMovement[];
  stockTransfers: StockTransfer[];
  stockReservations: StockReservation[];
  stockAdjustments: StockAdjustment[];
  quotations: Quotation[];
  salesOrders: SalesOrder[];
  deliveries: Delivery[];
  salesInvoices: SalesInvoice[];
  customerReturns: CustomerReturn[];
  purchaseRequests: PurchaseRequest[];
  purchaseOrders: PurchaseOrder[];
  goodsReceipts: GoodsReceipt[];
  supplierBills: SupplierBill[];
  purchaseReturns: PurchaseReturn[];
  accounts: Account[];
  journalEntries: JournalEntry[];
  journalLines: JournalLine[];
  payments: Payment[];
  paymentAllocations: PaymentAllocation[];
  fiscalPeriods: FiscalPeriod[];
  expenses: Expense[];
  departments: Department[];
  employees: Employee[];
  attendance: Attendance[];
  leaveRequests: LeaveRequest[];
  payrollRuns: PayrollRun[];
  approvals: Approval[];
  auditLog: AuditLog[];
  documentSequences: DocumentSequence[];
}
